njs_inline uint32_t
njs_scope_index_value(njs_index_t index)
{
    return (uint32_t) (index >> NJS_SCOPE_VALUE_OFFSET);
}


njs_inline njs_value_t *
njs_scope_value(njs_vm_t *vm, njs_index_t index)
{
    njs_value_t       **level;
    njs_level_type_t  type;

    type = njs_scope_index_type(index);

    level = vm->levels[type];
    if (njs_slow_path(level == NULL)) {
        /*
         * Invalid bytecode or corrupted VM state.
         * Prevent NULL pointer dereference (zero-page read) in the interpreter.
         */
        njs_internal_error(vm, "scope level is not set");
        return NULL;
    }

    return level[njs_scope_index_value(index)];
}


njs_inline njs_value_t *
njs_scope_valid_value(njs_vm_t *vm, njs_index_t index)
{
    njs_value_t  *value;

    value = njs_scope_value(vm, index);
    if (njs_slow_path(value == NULL)) {
