   472	    } else {
   473	        spare_size = size + NJS_FRAME_SPARE_SIZE;
   474	        spare_size = njs_align_size(spare_size, NJS_FRAME_SPARE_SIZE);
   475	
   476	        if (spare_size > vm->spare_stack_size) {
   477	            njs_range_error(vm, "Maximum call stack size exceeded");
   478	            return NULL;
   479	        }
   480	
   481	        frame = njs_mp_align(vm->mem_pool, sizeof(njs_value_t), spare_size);
   482	        if (njs_slow_path(frame == NULL)) {
   483	            njs_memory_error(vm);
   484	            return NULL;
   485	        }
   486	
   487	        chunk_size = spare_size;
   488	        vm->spare_stack_size -= spare_size;
   489	    }
   490	
   491	    njs_memzero(frame, sizeof(njs_native_frame_t));
