   493	    frame->size = chunk_size;
   494	    frame->free_size = spare_size - size;
   495	    frame->free = (u_char *) frame + size;
   496	
   497	    frame->previous = vm->top_frame;
   498	    vm->top_frame = frame;
   499	
   500	    return frame;
